  [424573] = { "Ferito: subisce danni nel tempo e altri effetti debilitanti.", "Ferito: subisce danni nel tempo e altri effetti debilitanti.", 0xe7b7d961, 0xe7b7d961, "uu" },
  [424574] = { "Esausto.", "Esausto.", 0x0c78d890, 0x0c78d890, "uu" },
  [424645] = { "Traduci gli appunti dell'incantesimo in una nuova ricetta d'incisione runica. Richiede un riferimento per la stenografia dell'autore.", nil, 0xadb28b80, nil, "um" },
  [424715] = { "Ottieni l'abilità Cometa Arcana:\n\n$I1\nScaglia energie stellari impetuose che infliggono $N1 danni da arcano e aumentano del $N3% i danni dei tuoi prossimi $N2 lanci di Fuoco Stellare per $D1.\n\nCometa Arcana beneficia e attiva la maggior parte dei talenti e degli effetti che attivano Ira Silvana o Fuoco Stellare o ne beneficiano.", nil, 0xb4f41bbf, nil, "um" },
  [424718] = { "Incidi sui tuoi gambali la runa Cometa Arcana:\n\n$I1\nScaglia energie stellari impetuose che infliggono $N1 danni da arcano e aumentano del $N3% i danni dei tuoi prossimi $N2 lanci di Fuoco Stellare per $D1.\n\nCometa Arcana beneficia e attiva la maggior parte dei talenti e degli effetti che attivano Ira Silvana o Fuoco Stellare o ne beneficiano.", nil, 0x9a8618a9, nil, "um" },
  [424759] = { { "Ottieni l'abilità Berserk:\n\n$I1\n|CFFFFFFFFRichiede Forma Felina, Forma d'Orso, Dire Bear Form|R\nLa tua abilità Morso Primordiale colpisce fino a $N1 bersagli e non ha più tempo di recupero, e la probabilità di critico delle tue abilità che generano punti combo aumenta del $N2%. Per la durata dell'effetto rimuove gli effetti di paura e rende immune a essi. Dura $D1.", "Ottieni l'abilità Berserk:\n\n$I1\n|CFFFF2020Richiede Forma Felina, Forma d'Orso, Dire Bear Form|R\nLa tua abilità Morso Primordiale colpisce fino a $N1 bersagli e non ha più tempo di recupero, e la probabilità di critico delle tue abilità che generano punti combo aumenta del $N2%. Per la durata dell'effetto rimuove gli effetti di paura e rende immune a essi. Dura $D1.", shape = { "3/1", "3/1" }, key = { "8cd9df0167ae5083", "1da9dba7e327f612" } }, nil, 0x1cd4f479, nil, "um" },
  [424760] = { { "Incidi sulla tua cintura la runa Berserk:\n\n$I1\n|CFFFFFFFFRichiede Forma Felina, Forma d'Orso, Dire Bear Form|R\nLa tua abilità Morso Primordiale colpisce fino a $N1 bersagli e non ha più tempo di recupero, e la probabilità di critico delle tue abilità che generano punti combo aumenta del $N2%. Per la durata dell'effetto rimuove gli effetti di paura e rende immune a essi. Dura $D1.", "Incidi sulla tua cintura la runa Berserk:\n\n$I1\n|CFFFF2020Richiede Forma Felina, Forma d'Orso, Dire Bear Form|R\nLa tua abilità Morso Primordiale colpisce fino a $N1 bersagli e non ha più tempo di recupero, e la probabilità di critico delle tue abilità che generano punti combo aumenta del $N2%. Per la durata dell'effetto rimuove gli effetti di paura e rende immune a essi. Dura $D1.", shape = { "3/1", "3/1" }, key = { "e3f547b4846b6b2c", "b0b0701c0b971880" } }, nil, 0xcfb3cf54, nil, "um" },
  [424762] = { "Ottieni l'abilità Re della Giungla:\n\n$I1\nFuria della Tigre ora ti fornisce istantaneamente $N1 energia.", nil, 0xfb8ee464, nil, "um" },
  [424765] = { "Incidi sui tuoi stivali la runa Re della Giungla:\n\n$I1\nFuria della Tigre ora ti fornisce istantaneamente $N1 energia.", nil, 0xd414c04d, nil, "um" },
  [424785] = { "Colpisce brutalmente un nemico con un fendente, infliggendo il $N1% dei danni dell'arma, e fa sanguinare il bersaglio, infliggendo $N2 danni ogni $D1 per $D2, effetto cumulabile fino a $N5 volte. Ogni applicazione aumenta inoltre del $N6% i danni inflitti da Fendente di Sciabola e ⟦Sinister Strike=Assalto Funesto⟧. Fornisce $N7 punti combo.\n\nFendente di Sciabola beneficia di tutti i talenti e gli effetti che si attivano con ⟦Sinister Strike=Assalto Funesto⟧ o lo modificano.", "Sanguinamento: $N1 danni ogni $D1.\nDanni subiti da Fendente di Sciabola e ⟦Sinister Strike=Assalto Funesto⟧ aumentati del $N3%.", 0x72e45558, 0x7fbbf470, "uu" },
  [424788] = { "Recupera pezzi di ricambio dai rottami di un segatronchi.", nil, 0x30b9e1d2, nil, "um" },
  [424799] = { "Attacca istantaneamente con l'arma nella mano secondaria, infliggendo i normali danni dell'arma secondaria con il $N1% di probabilità di applicare al bersaglio il veleno dell'arma secondaria. Le armi più lente richiedono più energia. Fornisce $N2 punti combo.\n\nStilettata beneficia di tutti i talenti e gli effetti che si attivano con ⟦Sinister Strike=Assalto Funesto⟧ o lo modificano.", nil, 0xb5aa7d3f, nil, "um" },
  [424800] = { "Attacca istantaneamente con l'arma nella mano secondaria, infliggendo i normali danni dell'arma secondaria con il $N1% di probabilità di applicare al bersaglio il veleno dell'arma secondaria. Le armi più lente richiedono più energia. Fornisce $N2 punti combo.", nil, 0x282f1a89, nil, "um" },
  [424919] = { "Colpisce istantaneamente con l'arma nella mano secondaria, infliggendo i normali danni dell'arma secondaria, e aumenta la tua probabilità di parata del $N1% per $D1 o finché non pari con successo un attacco. Per $D2 dopo l'uso di Doppio Attacco, ⟦Sinister Strike=Assalto Funesto⟧ costa $N4 energia in meno, genera il $N5% di minaccia in più e fornisce applicazioni di Rolling with the Punches, e sia ⟦Sinister Strike=Assalto Funesto⟧ sia Sventramento infliggono il $N6% di danni in più. Fornisce $N7 punti combo.\n\nDoppio Attacco beneficia della maggior parte dei talenti e degli effetti che si attivano con ⟦Sinister Strike=Assalto Funesto⟧ o lo modificano. L'effetto di Doppio Attacco non riduce il costo né potenzia Doppio Attacco.", "Probabilità di parata aumentata del $N1%.", 0xc4245e6a, 0xea59a9be, "uu" },
  [424925] = { { "Riduce di $N1 il costo in energia delle tue abilità Pugnalata alle Spalle e Imboscata e aumenta del $N2% i danni che infliggono ai bersagli non controllati da giocatori. Non si applica a Mutilazione.", "Riduce di $N1 il costo in energia delle tue abilità Pugnalata alle Spalle e Imboscata e aumenta del $N2% i danni che infliggono ai bersagli non controllati da giocatori. Non si applica alle abilità apprese da altre rune.", shape = { "2/0", "2/0" }, key = { "22f97d0538fee5c2", "ba2b470676de221a" } }, nil, 0x2c1b4225, nil, "um" },
  [424979] = { "Ottieni l'abilità Fendente di Sciabola:\n\n$I1\nColpisce brutalmente un nemico con un fendente, infliggendo il $N1% dei danni dell'arma, e fa sanguinare il bersaglio, infliggendo $N2 danni ogni $D1 per $D2, effetto cumulabile fino a $N5 volte. Ogni applicazione aumenta inoltre del $N6% i danni inflitti da Fendente di Sciabola e Assalto Funesto. Fornisce $N7 punti combo.\n\nFendente di Sciabola beneficia di tutti i talenti e gli effetti che si attivano con Assalto Funesto o lo modificano.", nil, 0xd3ed0eab, nil, "um" },
  [424980] = { "Ottieni l'abilità Cutthroat:\n\n$I1\nPugnalata alle Spalle ha il $N1% di probabilità di far sì che la tua prossima Imboscata entro $D1 non richieda Furtività.", nil, 0xc5e9cf59, nil, "um" },
  [424982] = { "Ottieni l'abilità Doppio Attacco:\n\n$I1\nColpisce istantaneamente con l'arma nella mano secondaria, infliggendo i normali danni dell'arma secondaria, e aumenta la tua probabilità di parata del $N1% per $D1 o finché non pari con successo un attacco. Per $D2 dopo l'uso di Doppio Attacco, Assalto Funesto costa $N4 energia in meno, genera il $N5% di minaccia in più e fornisce applicazioni di Rolling with the Punches, e sia Assalto Funesto sia Sventramento infliggono il $N6% di danni in più. Fornisce $N7 punti combo.\n\nDoppio Attacco beneficia della maggior parte dei talenti e degli effetti che si attivano con Assalto Funesto o lo modificano. L'effetto di Doppio Attacco non riduce il costo né potenzia Doppio Attacco.", nil, 0xb2b7138c, nil, "um" },
  [424983] = { { "Ottieni l'abilità Slaughter from the Shadows:\n\n$I1\nRiduce di $N1 il costo in energia delle tue abilità Pugnalata alle Spalle e Imboscata e aumenta del $N2% i danni che infliggono ai bersagli non controllati da giocatori. Non si applica a Mutilazione.", "Ottieni l'abilità Slaughter from the Shadows:\n\n$I1\nRiduce di $N1 il costo in energia delle tue abilità Pugnalata alle Spalle e Imboscata e aumenta del $N2% i danni che infliggono ai bersagli non controllati da giocatori. Non si applica alle abilità apprese da altre rune.", shape = { "2/0", "2/0" }, key = { "086361f66bc2f8ce", "6566e6c0231a7c6d" } }, nil, 0x9b32cf65, nil, "um" },
  [424984] = { "Incidi sui tuoi guanti la runa Fendente di Sciabola:\n\n$I1\nColpisce brutalmente un nemico con un fendente, infliggendo il $N1% dei danni dell'arma, e fa sanguinare il bersaglio, infliggendo $N2 danni ogni $D1 per $D2, effetto cumulabile fino a $N5 volte. Ogni applicazione aumenta inoltre del $N6% i danni inflitti da Fendente di Sciabola e Assalto Funesto. Fornisce $N7 punti combo.\n\nFendente di Sciabola beneficia di tutti i talenti e gli effetti che si attivano con Assalto Funesto o lo modificano.", nil, 0x9ee44fa7, nil, "um" },
  [424988] = { "Incidi sui tuoi guanti la runa Cutthroat:\n\n$I1\nPugnalata alle Spalle ha il $N1% di probabilità di far sì che la tua prossima Imboscata entro $D1 non richieda Furtività.", nil, 0xe753d816, nil, "um" },
  [424990] = { "Incidi sui tuoi guanti la runa Doppio Attacco:\n\n$I1\nColpisce istantaneamente con l'arma nella mano secondaria, infliggendo i normali danni dell'arma secondaria, e aumenta la tua probabilità di parata del $N1% per $D1 o finché non pari con successo un attacco. Per $D2 dopo l'uso di Doppio Attacco, Assalto Funesto costa $N4 energia in meno, genera il $N5% di minaccia in più e fornisce applicazioni di Rolling with the Punches, e sia Assalto Funesto sia Sventramento infliggono il $N6% di danni in più. Fornisce $N7 punti combo.\n\nDoppio Attacco beneficia della maggior parte dei talenti e degli effetti che si attivano con Assalto Funesto o lo modificano. L'effetto di Doppio Attacco non riduce il costo né potenzia Doppio Attacco.", nil, 0x279ea807, nil, "um" },
  [424992] = { { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Slaughter from the Shadows:\n\n$I1\nRiduce di $N1 il costo in energia delle tue abilità Pugnalata alle Spalle e Imboscata e aumenta del $N2% i danni che infliggono ai bersagli non controllati da giocatori. Non si applica a Mutilazione.", "Incidi sulla tua armatura per il torso o sulla tua veste la runa Slaughter from the Shadows:\n\n$I1\nRiduce di $N1 il costo in energia delle tue abilità Pugnalata alle Spalle e Imboscata e aumenta del $N2% i danni che infliggono ai bersagli non controllati da giocatori. Non si applica alle abilità apprese da altre rune.", shape = { "2/0", "2/0" }, key = { "cacd922347a2d5f8", "4ff57943e24aa99c" } }, nil, 0x9ddaea85, nil, "um" },
